def handle(app, svc):
    result = svc.apply(app)
    decision = result.get("decision")
    limit = result.get("limit", 0)

    # Network referral rule: self_employed applicant with requested_limit
    # above 6000 must go to manual review instead of being issued.
    # A decline stays a decline.
    if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000:
        if decision == "decline":
            return {"action": "decline", "limit": 0}
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    # refer / not decided -> manual review queue
    return {"action": "queue_review", "limit": 0}
